window.BUGS=[{"app":"Finished.","category":"security","title":"Anon could enumerate every user's media files","symptom":"A signed-out user could list('') the media bucket and enumerate all users' folders and files.","root_cause":"The storage SELECT policy allowed anon to list the whole bucket.","fix":"Migration lock_media_bucket_select_to_own_folder scoped SELECT to authenticated users and their own folder; verified playback still works.","session":"a951a7c7"},{"app":"Finished.","category":"security","title":"Could not post multiple / photo stories","symptom":"Posting more than one story (specifically photo stories) failed with 'new row violates row-level security policy'.","root_cause":"A storage RLS issue on the media bucket blocked the upsert for photo stories (text-only worked).","fix":"Added an additive own-folder UPDATE policy on storage so photo/multi stories post.","session":"8c8cbb86"},{"app":"Finished.","category":"security","title":"Cross-account local data leak on shared device","symptom":"Signing into a second account on the same device exposed the first account's countdowns, notes, trackers and voice notes.","root_cause":"Local content was stored device-globally with no per-account scoping; the reset flow leaked the same way.","fix":"Added accountScope.ts to stamp finished.owner-uid on sign-in, wipe on switch, and made push/pull re-check ownership so a race can't cross accounts; cleaned the leaked rows.","session":"d42b1fb3"},{"app":"Finished.","category":"security","title":"Cross-user data leak on account switch","symptom":"After switching accounts locally, a user saw another user's celebration countdowns.","root_cause":"signOut() did not wipe local user data and account-switch left stale React state.","fix":"Sign-out now wipes all local user content and Switch account hard-reloads; committed as a P0 fix.","session":"fd796bb1"},{"app":"Finished.","category":"security","title":"Dangerous RPCs callable from client","symptom":"Privileged operations read_vault_secret and add_credits were reachable from the client.","root_cause":"Sensitive server functions were exposed to the client surface.","fix":"Removed them so read_vault_secret and add_credits no longer appear/are callable.","session":"0b6b99f5"},{"app":"Finished.","category":"security","title":"Database SECURITY DEFINER / search_path hardening","symptom":"SECURITY DEFINER views bypassed RLS and could re-leak protected tables, and functions had mutable search_path; some policies trusted user-editable user_metadata.","root_cause":"Advisor lints 0010 (definer views) and 0015 (user_metadata policies) plus mutable search_path across functions.","fix":"Locked down the SECURITY DEFINER surface, fixed the mutable search_path across functions, and stopped trusting user_metadata.","session":"d42b1fb3"},{"app":"Finished.","category":"security","title":"Deleting posts/stories orphaned uploaded media","symptom":"Deleting a post or story left its photo/video fetchable by URL forever, and avatar changes orphaned the old file.","root_cause":"deletePost/deleteStory removed only the DB row, not the storage file.","fix":"Delete now also removes the associated storage file; verified.","session":"a951a7c7"},{"app":"Finished.","category":"security","title":"Email column readable via profiles","symptom":"The profiles table exposed users' email addresses.","root_cause":"No column-level restriction on the profiles select surface.","fix":"Applied column-level grants so only id, handle, full_name, avatar_url, bio, plan are readable; selecting email now returns permission denied.","session":"d42b1fb3"},{"app":"Finished.","category":"security","title":"email_for_handle revoke left a silent PUBLIC ACL hole","symptom":"A Postgres function remained accessible to PUBLIC despite a revoke.","root_cause":"The staged email_for_handle revoke omitted PUBLIC from the ACL.","fix":"Revoked PUBLIC live and fixed the staged migration to include PUBLIC.","session":"b7a703ad"},{"app":"Finished.","category":"security","title":"Missing CSP and security headers","symptom":"The app shipped with no Content-Security-Policy or security headers.","root_cause":"An inline boot script prevented a strict script-src 'self' policy.","fix":"Externalized the boot script to /boot.js and added a strict CSP plus security headers.","session":"d42b1fb3"},{"app":"Finished.","category":"security","title":"Private 'Only me' posts leaked to friends","symptom":"Posts set to private were visible to friends.","root_cause":"The RLS friends branch checked is_friend regardless of the post's audience.","fix":"Tightened the RLS policy so private posts are author-only.","session":"8c8cbb86"},{"app":"Finished.","category":"security","title":"Source files leaked over HTTP","symptom":"`/package.json`, `/vite.config.ts`, `/src/*` and other repo files were served as real files.","root_cause":"The broken Pages config served the repo root instead of the SPA build.","fix":"With the build config fixed, those paths now fall through to the SPA shell (text/html) instead of leaking source.","session":"0f95b04e"},{"app":"Finished.","category":"security","title":"Stale tab survives account switch and re-uploads data","symptom":"A second open tab that survived an account switch could re-save and re-upload the previous user's data.","root_cause":"The old tab kept the previous account's in-memory state after the switch.","fix":"Closed this cross-account leak path so a surviving tab can't re-upload old data.","session":"d42b1fb3"},{"app":"Finished.","category":"security","title":"Stripe webhook rejected all payments (Verify JWT on)","symptom":"Billing was dead; every paying customer got no credits or subscription.","root_cause":"stripe-webhook had Verify JWT ON, so Stripe's signature-carrying webhooks were rejected with 401 before reaching the code.","fix":"Turned verify_jwt off so the webhook reaches the code and verifies the Stripe signature (verified 401 became 400).","session":"8c8cbb86"},{"app":"Finished.","category":"security","title":"Unauthenticated translate endpoint abuse","symptom":"Anyone could hammer the pre-login translate endpoint with 640K chars per request, risking runaway cost.","root_cause":"The endpoint ran before login with no rate limit and no size cap.","fix":"Added a hard total-chars-per-request cap plus per-IP rate limiting; deployed and verified live.","session":"a951a7c7"},{"app":"Finished.","category":"data-loss","title":"Deleted celebrations resurrect","symptom":"Deleted celebrations could reappear after the new sync engine ran.","root_cause":"The new sync engine lacked deletion handling for these records.","fix":"Fixed the related sync flaw so deletions persist.","session":"04df6fb8"},{"app":"Finished.","category":"data-loss","title":"Deleting a recording did not unshare or remove the file","symptom":"Deleting a recording left the shared row and cloud file fetchable.","root_cause":"deleteRecording only removed the local row.","fix":"unshareRecording() now deletes the recordings row and the stored cloud file.","session":"a951a7c7"},{"app":"Finished.","category":"data-loss","title":"Deletions resurrect in synced IndexedDB stores","symptom":"Deletions across seven synced IndexedDB stores (docs, flashcards, memos, homework, trackers, snips, book notes) reappeared within ~25 seconds.","root_cause":"Only localStorage stores had tombstones, so IndexedDB deletions were re-pulled from the cloud.","fix":"Added tombstones to the IndexedDB stores so deletions stick.","session":"d42b1fb3"},{"app":"Finished.","category":"data-loss","title":"Recording lost on crash or full disk","symptom":"When the disk filled or the tab crashed/OOMed, the entire recording was lost.","root_cause":"Chunks were held in an in-memory array flushed only at stop time.","fix":"Journal each ~1s chunk to IndexedDB as it's captured and assemble on save (crash-proof).","session":"eae12f03"},{"app":"Finished.","category":"data-loss","title":"Recordings local-only by default risked loss","symptom":"A lost device meant lost video because recordings stayed local.","root_cause":"streamCloud defaulted to false, framed as a niche storage-saver.","fix":"Cloud streaming now defaults ON when signed in.","session":"a951a7c7"},{"app":"Finished.","category":"data-loss","title":"Seed calendar has self-overlapping event","symptom":"A conflict flagged 'Standup overlaps Standup'.","root_cause":"The seed data created a duplicate overlapping event.","fix":"Fixed the seed data.","session":"4237597d"},{"app":"Finished.","category":"data-loss","title":"Stale device overwrites newer cloud journal notes","symptom":"A stale device could silently overwrite newer journal notes in the cloud, and concurrent syncs could interleave.","root_cause":"Re-sync wrote unchanged content back over newer cloud data with no change detection or serialization.","fix":"Hash-skip unchanged journals on re-sync (no stale clobber) and guarded concurrent syncs.","session":"d42b1fb3"},{"app":"Finished.","category":"crash","title":"Broken main build referencing SignInLoader before it existed","symptom":"App.tsx referenced SignInLoader which was never created, leaving main with a broken build.","root_cause":"A concurrent edit committed the reference before the component file existed.","fix":"Created the branded sign-in loader component to restore a green build.","session":"8c8cbb86"},{"app":"Finished.","category":"crash","title":"Calendar crashes on unrecognised event kind","symptom":"Any event kind the calendar did not recognise took down the whole calendar view.","root_cause":"calendar.js indexed KINDS[e.kind].color directly with no guard for unknown kinds.","fix":"Guarded the KINDS lookup so unknown event kinds no longer crash the view.","session":"9033ea59"},{"app":"Finished.","category":"crash","title":"Deployed app stuck on blank/loading screen on Cloudflare","symptom":"The Cloudflare-hosted app and custom domain showed only a blank/continuous loading screen; localhost worked.","root_cause":"A stale/poisoned service worker served an old index.html pointing at asset hashes that no longer exist, and sw.js was cacheable so the kill-switch never loaded.","fix":"Forced sw.js/index.html to never cache, added a kill-switch SW that self-unregisters, an inline boot-script SW purge, an error boundary, and SPA _redirects.","session":"8c8cbb86"},{"app":"Finished.","category":"crash","title":"Library crash on malformed record","symptom":"Library.tsx crashed calling .slice on undefined while mapping records missing a title.","root_cause":"A record missing the title field wasn't guarded against.","fix":"Added a defensive guard at the crash point to harden Library against malformed records.","session":"d42b1fb3"},{"app":"Finished.","category":"crash","title":"PDF cover render hang","symptom":"Loading a PDF whose fonts can't render to canvas hung the app on cover generation.","root_cause":"Cover render blocked when embedded fonts couldn't rasterize.","fix":"Added useSystemFonts:true plus a cover-render timeout race, falling back to a monogram cover.","session":"0b6b99f5"},{"app":"Finished.","category":"crash","title":"Split React import","symptom":"A split/duplicated React import broke the build for the new UI bits.","root_cause":"React was imported in two conflicting statements.","fix":"Fixed the split React import and added the needed CSS.","session":"879d06ee"},{"app":"Finished.","category":"crash","title":"Study page missing i18n import","symptom":"The Study page failed because a required i18n import was missing.","root_cause":"The i18n module wasn't imported into Study after localization was added.","fix":"Added the i18n import and rebuilt.","session":"0b6b99f5"},{"app":"Finished.","category":"crash","title":"White screen — app never mounts","symptom":"Production showed a white screen (later a stuck splash) because the deployed JS never mounted #root.","root_cause":"The Cloudflare Pages project had no build step (output = repo root), so it served raw source and index.html referenced asset hashes that didn't exist.","fix":"Corrected the Pages build config (output dir `dist`) and deployed the real build so the entry module returns 200 application/javascript and the app mounts.","session":"0f95b04e"},{"app":"Finished.","category":"auth","title":"Cannot add posts, photos, stories, or profile photos","symptom":"Post/photo/story/profile-photo uploads all failed.","root_cause":"The media storage bucket was missing a scoped read policy (a privacy pass had dropped it), so authenticated reads of new media rows failed.","fix":"Applied a migration restoring the `read media rows` policy plus client-side hardening in cloud.ts, fixing production instantly.","session":"ec6dbc01"},{"app":"Finished.","category":"auth","title":"Profile can't add photos or posts","symptom":"Users couldn't add new profile photos or posts.","root_cause":"Writes reached Supabase as anon due to a stale/invalid client session, so correct RLS blocked avatar upload, post insert, and profile update.","fix":"Hardened isAuthError/throwIfError to recognize storage auth failures so a bad session is refreshed-and-retried, then sent to re-sign-in.","session":"c0359013"},{"app":"Finished.","category":"auth","title":"Signed-in users saw 'Sign in' and no credits after reload","symptom":"Returning users (page reload with an existing session) saw 'Sign in' and dashes instead of their name and credit balance.","root_cause":"getProfile/ensureProfile/me()/myPlan/listInvoices used getUser() (a network call that returns null on a hiccup).","fix":"Switched to getSession() (local + auto-refresh) and made the menu re-fetch on open.","session":"8c8cbb86"},{"app":"Finished.","category":"auth","title":"Signup blocked by email confirmation","symptom":"Signup was completely blocked, requiring email confirmation that often failed.","root_cause":"Account creation depended on Supabase email-confirmation which was gated by a dashboard toggle.","fix":"Added an edge function that creates confirmed accounts server-side and routed client signup through it, plus live handle-availability checks.","session":"0b6b99f5"},{"app":"Finished.","category":"auth","title":"Signup email rate-limit trap","symptom":"Signup failed with \"Email rate limit exceeded\" after a user corrected a mistyped email and retried.","root_cause":"Supabase's built-in mailer cap (~2 confirmation emails/hour) was hit by the retry.","fix":"Shipped fixes so the signup flow no longer trips the confirmation-email cap.","session":"0b6b99f5"},{"app":"Finished.","category":"auth","title":"Social actions silently fail on a lapsed token","symptom":"Stories, profile photo, adding posts and follow/unfollow appeared not to work with no error.","root_cause":"Client errors were swallowed and follow/unfollow failed silently when the auth token had lapsed.","fix":"Routed writes through `authedWrite` (refresh-and-retry) and surfaced errors, with an optimistic follow toggle and live count refresh.","session":"eae12f03"},{"app":"Finished.","category":"auth","title":"Stale auth session causes RLS write failures","symptom":"Posting failed with \"new row violates row-level security policy\" and profile-photo updates silently didn't work.","root_cause":"A broken/expired client auth session sent writes to Supabase as anon, which correct RLS then blocked (avatar upload, post insert, profile update).","fix":"Made me() proactively refresh the token, persist+auto-refresh the session, refresh-before-write, retry once, and re-prompt sign-in instead of showing a raw DB error.","session":"04df6fb8"},{"app":"Finished.","category":"sync","title":"Celebrations don't sync across devices","symptom":"Celebrations added on one device didn't appear on the same account on another device.","root_cause":"Countdowns/celebrations were localStorage-only (finished.countdowns) and never pushed to the cloud.","fix":"Synced them to the user_data cloud table like notes/trackers.","session":"04df6fb8"},{"app":"Finished.","category":"sync","title":"Home tools grid needs a reload to show Calendar/Bookings/Task Manager","symptom":"Users had to reload the whole app before Calendar, Bookings and Task Manager appeared in the tools grid.","root_cause":"The home 'Tools' grid seeded once from localStorage, and cloud sync rewrote the tiles list but fired the wrong event, so the grid never refreshed.","fix":"Re-read the tiles after a cloud sync (on the correct event) so tiles appear without a reload.","session":"eae12f03"},{"app":"Finished.","category":"sync","title":"Sync pulls truncated at 1,000 rows","symptom":"Cloud pulls were capped at 1,000 rows, dropping data beyond that.","root_cause":"The pull query hit the default 1,000-row limit without pagination.","fix":"Fixed the sync engine so pulls aren't truncated at 1,000 rows.","session":"d42b1fb3"},{"app":"Finished.","category":"race","title":"Camera stayed on after closing the recorder","symptom":"The device camera remained active after the user exited the journal recorder.","root_cause":"A classic async race left the media stream running on exit.","fix":"Added a cancelled flag, nulled srcObject, and stopped the recorder on exit.","session":"8c8cbb86"},{"app":"Finished.","category":"race","title":"Loading splash kept randomly reappearing","symptom":"After adding the splash, the loading splash kept popping up randomly.","root_cause":"main.tsx re-registered the service worker on every load and the kill-switch SW called client.navigate() on activate, creating a re-register/re-activate/reload loop; also a timer-vs-network reload race.","fix":"Stopped the SW reload loop so the boot script only recovers on genuine breakage (stale SW controls page → one reload).","session":"8c8cbb86"},{"app":"Finished.","category":"race","title":"PIN pad rapid-tap race","symptom":"Fast typing on the PIN pad could drop a digit.","root_cause":"","fix":"Fixed the rapid-tap race so each keypress builds on the latest state and auto-submits on the 5th digit.","session":"0b6b99f5"},{"app":"Finished.","category":"race","title":"Rapid taps overwrite previous setting","symptom":"Rapidly tapping a setting lost the previous value.","root_cause":"A stale-closure overwrite meant each tap read an outdated state.","fix":"Fixed it so each tap builds on the latest state.","session":"4e54d91b"},{"app":"Finished.","category":"race","title":"Read-aloud voice was monotone then kept switching voices","symptom":"Pressing play started with a robotic/monotone voice then switched to a different voice on each sentence.","root_cause":"speak() fired before the browser voices finished loading (using the robotic default), and the fallback could land on a novelty voice.","fix":"Waited for voices to load, resolved the chosen voice once, pinned it across all sentences, and blocklisted novelty voices.","session":"8c8cbb86"},{"app":"Finished.","category":"race","title":"Same-tick taps cancel each other","symptom":"Two same-instant taps could cancel each other out.","root_cause":"A race between two same-tick actions.","fix":"Fixed the race so both same-tick actions now stick; verified in browser.","session":"fd796bb1"},{"app":"Finished.","category":"race","title":"Sync race causing three sync defects","symptom":"Three sync defects surfaced during testing.","root_cause":"A genuine race condition in the sync path.","fix":"Fixed the race at its cause, resolving all three sync defects.","session":"9033ea59"},{"app":"Finished.","category":"logic","title":"'See Plus' button was a dead-end","symptom":"Clicking 'See Plus' did nothing.","root_cause":"","fix":"Wired 'See Plus' to open the plan-selection screen.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Assistant claims success for no-op actions on Pro","symptom":"On Pro, asking the assistant to add a milestone, start a timer or invite a teammate created nothing yet it did not fail honestly (or returned the wrong hour).","root_cause":"The assistant reported success for actions that never actually executed.","fix":"Corrected the action wiring/reporting so it no longer claims success for nothing.","session":"9033ea59"},{"app":"Finished.","category":"logic","title":"Celebration inline edits not saving","symptom":"Editing celebrations directly on the main screen didn't work.","root_cause":"Reproduced and root-caused in the browser (not theorized).","fix":"Fixed the main-screen celebration edit path so edits apply.","session":"04df6fb8"},{"app":"Finished.","category":"logic","title":"Could sign up without choosing a plan/price","symptom":"Signup completed without the user selecting a price.","root_cause":"","fix":"Required a plan pick during signup.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Countdown count-up broken","symptom":"Birthday/anniversary countdowns didn't count down or up correctly.","root_cause":"","fix":"Fixed count-up and added days+hours, dd/mm/yyyy dates, and a repeats-every-year toggle.","session":"0b6b99f5"},{"app":"Finished.","category":"logic","title":"Credit price mismatch between display and checkout","symptom":"The app showed $19 for 100 credits while checkout charged $50, and two credit tiles 404'd.","root_cause":"Pricing was not driven by a single source of truth across app, create-checkout, and Stripe.","fix":"Introduced a canonical credits.ts tier table used everywhere so display matches checkout ($19 = 100 credits).","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Day/Night toggle did not actually flip themes","symptom":"Switching the Day/Night toggle did not reliably change modes.","root_cause":"Midnight was secretly both a selectable colourway and the dark mode.","fix":"Separated Midnight from dark mode so the Day/Night toggle now flips correctly.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Duplicate SlotEditor block in Scheduler edit","symptom":"Scheduler edit rendered a duplicated slot editor.","root_cause":"A stray duplicate {adding !== null && <SlotEditor>} block was present.","fix":"Removed the stray duplicate block.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Empty Clipboard click did nothing","symptom":"Clicking the Clipboard section when it was empty produced no response.","root_cause":"The section only rendered if the user already had clipboard grabs, so an empty clipboard showed nothing.","fix":"Made the Clipboard render and respond even when empty.","session":"0b6b99f5"},{"app":"Finished.","category":"logic","title":"Google Translate silently returned untranslated text","symptom":"Live Google Translate did not actually translate in the UI.","root_cause":"The client hit the Cloudflare no-key echo first (silently short-circuiting), and the Supabase translate function read the key from the wrong secret location.","fix":"Made the client call the Supabase function first and skip the no-key echo, and made Supabase translate read the key from the Vault.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Handle-availability indicator showed a stale result","symptom":"The username handle checker showed a stale ✓ available against a name that was actually taken.","root_cause":"The indicator kept the previous handle's result while the user typed the next character (client-side stale state); the RPC itself was fine.","fix":"Fixed the stale state and added an authoritative re-check on submit.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Insert-table button could not add rows or columns","symptom":"In docs, the insert-table feature didn't let users add rows and columns.","root_cause":"","fix":"Wired the table popover to add rows/columns.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Mic re-captures tab audio (echo)","symptom":"Recordings had echo from the mic picking up the tab's own audio.","root_cause":"The microphone re-captured the tab audio output.","fix":"Applied the researched echo fix to the audio routing.","session":"eae12f03"},{"app":"Finished.","category":"logic","title":"New accounts got the 'Close friends' circle added twice","symptom":"A new account had two 'Close friends' circles seeded.","root_cause":"Circle seeding was not idempotent.","fix":"Made seeding idempotent (select + limit(1)) plus a DB unique index, and cleaned the existing duplicate.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"NLP leaves attendee name in event title","symptom":"'Priya' stayed in the event title instead of becoming a guest chip.","root_cause":"A bare weekday+time blocked the attendee match in the parser.","fix":"Fixed the parser so the attendee is extracted into a guest chip.","session":"4237597d"},{"app":"Finished.","category":"logic","title":"Page doesn't translate on language change","symptom":"Switching the language didn't translate the page.","root_cause":"Client-side language-switch logic didn't translate page content.","fix":"Implemented a whole-page auto-translator; verified English->French/Spanish with name and brand preserved.","session":"d42b1fb3"},{"app":"Finished.","category":"logic","title":"PDF cover-title letter-spacing extraction","symptom":"Letter-spaced PDF cover lines were mangled (e.g. \"H A L L A L U / I N T E L L I G E N C E\") and text was read out letter-by-letter instead of as whole words.","root_cause":"pdfjs-dist glyph-position line assembly didn't account for the wide inter-letter gaps of letter-spaced text.","fix":"Added per-line gap statistics (median x1.6), a collapse-regex safeguard, font-size heading detection with multi-line merge, and running-header removal.","session":"0b6b99f5"},{"app":"Finished.","category":"logic","title":"Six milestone module bugs","symptom":"Six reported milestone bugs affected the milestones feature.","root_cause":"Multiple distinct root causes traced to source across the milestones code.","fix":"Fixed all six milestone bugs at their root causes, each verified.","session":"9033ea59"},{"app":"Finished.","category":"logic","title":"Split translation strings produced garbled copy","symptom":"Translated sign-in copy came out garbled, e.g. 'Choisissez un 5Code PIN à 8 chiffres', and a card embedded the language name mid-sentence.","root_cause":"Phrases were split into multiple pieces (and a language name embedded mid-sentence) so each fragment translated separately.","fix":"Made each phrase a single string so it translates as one unit, and stopped embedding the language name mid-sentence.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Tracker empty-state showed 'under a minute' instead of '0 min'","symptom":"With zero tracked time, the Tracker showed 'under a minute' (x3) rather than 0 min.","root_cause":"The zero case fell through to the mins < 1 branch.","fix":"Added if (totalMinutes === 0) return '0 min' before the 'under a minute' branch.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Transcription not in the user's language","symptom":"Voice transcription didn't produce text in the user's selected language.","root_cause":"","fix":"Added a transcription-in-your-language fix alongside many more UI languages.","session":"0b6b99f5"},{"app":"Finished.","category":"logic","title":"Translate batch cap regression dropped half of each batch","symptom":"Legitimate localization batches would silently lose half their strings.","root_cause":"The client sends up to 128 strings per request but the new server ceiling was set to 64.","fix":"Raised the server per-request string ceiling to 128 in both the Supabase and Cloudflare versions.","session":"a951a7c7"},{"app":"Finished.","category":"logic","title":"UI strings (toasts, doc names) stayed in English when translating","symptom":"After switching language, many words stayed in English including toast messages and document names.","root_cause":"Hardcoded strings like showToast were not routed through the i18n/translation layer.","fix":"Wired showToast and other strings through the translation system with new i18n keys so translation propagates app-wide.","session":"8c8cbb86"},{"app":"Finished.","category":"logic","title":"Vault API key saved with trailing space","symptom":"AI features would silently break after wiring up the key.","root_cause":"The Vault secret was stored as \"ANTHROPIC_API_KEY \" with a trailing space in the key name.","fix":"Corrected/normalized the secret name so the key is read correctly.","session":"0b6b99f5"},{"app":"Finished.","category":"logic","title":"Word/character count differed between header and footer","symptom":"The same doc showed 57 words in the header and 117 in the footer.","root_cause":"The header (DocEditor) counted a stale plain-text content mirror while the footer (RichEditor) counted the live text.","fix":"Pointed the header count at the live text so header and footer both show the correct count.","session":"8c8cbb86"},{"app":"Finished.","category":"performance","title":"52 RLS initplan performance warnings","symptom":"RLS policies re-evaluated auth.uid() per row, flagged by 52 auth_rls_initplan advisories.","root_cause":"Policies called auth.uid() directly instead of a subselect.","fix":"Rewrote policies to use (select auth.uid()) per Supabase's recommendation.","session":"a951a7c7"},{"app":"Finished.","category":"performance","title":"Celebrations milliseconds re-render jank","symptom":"Opening celebrations glitched when many cards ran with milliseconds.","root_cause":"The whole list re-rendered every 60ms whenever any card displayed milliseconds.","fix":"Drove all cards from one shared requestAnimationFrame clock with per-value gated re-renders.","session":"879d06ee"},{"app":"Finished.","category":"performance","title":"Every-boot cache purge re-downloaded Whisper model","symptom":"Each visit forced a ~40MB Whisper model re-download.","root_cause":"The every-boot cache purge in main.tsx was deleting the Whisper model cache.","fix":"Scoped the boot purge so it no longer wipes the model cache (commit 58f6245).","session":"b7a703ad"},{"app":"Finished.","category":"performance","title":"Redundant duplicate profile fetches","symptom":"250+ duplicate profile fetches were issued per session.","root_cause":"Profile fetches weren't cached.","fix":"Cached the profile fetch for 30 seconds.","session":"04df6fb8"},{"app":"Finished.","category":"performance","title":"Screen recording freezes in a background tab","symptom":"Recordings froze whenever the tab was hidden or backgrounded.","root_cause":"The draw loop was visibility-throttled when the tab wasn't focused.","fix":"Drive the draw loop from a Web Worker timer with captureStream(0) + explicit requestFrame so capture isn't tied to compositing.","session":"eae12f03"},{"app":"Finished.","category":"performance","title":"Tracker Edit did nothing then lagged ~1s before opening","symptom":"Clicking Edit on a tracker appeared to do nothing, then the edit screen opened after a lag.","root_cause":"Tracker groups recomputed on each render causing ~1s open latency.","fix":"Memoised the tracker cards/groups via useMemo, cutting open time from ~1s to ~7ms.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"'20 free' credits wording was incorrect","symptom":"Copy said accounts start with 20 free when they actually start with 5.","root_cause":"Stale '20 free' wording in five places.","fix":"Changed '20 free' to '5 free' everywhere.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"'Add another tracker' button disappeared when trackers existed","symptom":"The tracker builder hid the add button once trackers already existed.","root_cause":"","fix":"Builder now always shows 'Add another tracker' even with existing trackers.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"'Add homework' line too dark to see in dark mode","symptom":"In homework, the add-homework line was too dark to read in dark mode.","root_cause":"","fix":"Lightened the add-homework line for dark-mode contrast.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"'Attach from library' opens an empty modal that does nothing","symptom":"Attaching from the library opened an empty modal where nothing happened.","root_cause":"The modal had no empty state and no upload path.","fix":"Added empty states and an upload CTA and wired the artifact viewer.","session":"bfc2eaa1"},{"app":"Finished.","category":"ui","title":"'Finished' wordmark rendered black in dark mode","symptom":"The 'Finished' wordmark (and every 'X.' header) turned black and vanished in dark mode.","root_cause":"The wordmark sat inside a <button>, which resets text color to black.","fix":"Set .brand color to var(--ink) / rgb(238,243,255) so the wordmark stays light in dark mode.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Add-to-story modal stuck and oversized","symptom":"Tapping \"add to story\" opened a modal that was stuck, too big, and falling off the page.","root_cause":"The modal had no height cap and the story preview wasn't constrained.","fix":"Capped the modal height with scroll and tightened the story preview.","session":"04df6fb8"},{"app":"Finished.","category":"ui","title":"App renders faded/flash on refresh","symptom":"The app randomly showed up faded when refreshed or reopened.","root_cause":"Loading-flash from the boot splash before the bundle loaded.","fix":"Shipped a new static splash and a loading-flash fix.","session":"04df6fb8"},{"app":"Finished.","category":"ui","title":"Archived section header looked broken/cramped","symptom":"The Archived section title rendered cramped/broken.","root_cause":"","fix":"Rebuilt it as a clean tappable pill '▾ Archived (n)' with one-tap Restore, and removed the 🗄 glyph.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Beautify blurred overlay unreadable","symptom":"The Beautify screen used a translucent blurred overlay that was hard to read.","root_cause":"It rendered as a blurred overlay rather than a solid page.","fix":"Replaced it with a fixed opaque full-screen page.","session":"eae12f03"},{"app":"Finished.","category":"ui","title":"Candy theme celebration tile text not readable","symptom":"In the Candy theme, the celebrations tile numbers/text were hard to see against the gradient.","root_cause":"","fix":"Made the celebration numbers white with a dark shadow (also fixed matcha/babypink) for contrast.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Coloured-card titles low contrast","symptom":"Titles on coloured cards rendered muted and hard to read.","root_cause":"","fix":"Fixed the titles to legible white for adequate contrast.","session":"04df6fb8"},{"app":"Finished.","category":"ui","title":"Confirm dialog used wrong verb for soft-cancel","symptom":"The Confirm dialog's action button read 'Delete' for a soft-cancel action.","root_cause":"Mislabeled action button verb.","fix":"Corrected the button label to match the soft-cancel action.","session":"6c59c3ad"},{"app":"Finished.","category":"ui","title":"Countdown numbers too small","symptom":"Countdown/count-up numbers were tiny and wrapped onto multiple lines.","root_cause":"","fix":"Made the numbers big and one line, down to milliseconds.","session":"04df6fb8"},{"app":"Finished.","category":"ui","title":"Cover-flow peek clicks closed the modal","symptom":"Clicking to peek in the cover-flow closed the whole modal.","root_cause":"Peek click events bubbled up to the veil's close handler.","fix":"Stopped the peek clicks from bubbling to the close handler.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"CTA button end rendered dark like it was cut off","symptom":"The end of the primary blue button looked dark/cut off, as if not fully rendered.","root_cause":"The gradient stop rendered a dark edge.","fix":"Set an explicit linear-gradient(135deg, #3b82f6, #4f93f8) on .onb-cta and .news-choice-btn.on so the button is fully blue.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Doc-editor header overcrowded and unclear","symptom":"The doc editor's top bar was a confusing strip where it wasn't clear what was on top vs bottom.","root_cause":"`.we-bar` was a single flex row cramming the title, word/char stats and ~10 tool controls.","fix":"Made `.we-bar` flex-wrap and protected the title so the toolbar wraps cleanly.","session":"eae12f03"},{"app":"Finished.","category":"ui","title":"Emoji picker didn't close on outside click","symptom":"Clicking outside the emoji picker left it open.","root_cause":"","fix":"Made the picker close when clicking anywhere outside it.","session":"0b6b99f5"},{"app":"Finished.","category":"ui","title":"Emoji picker horizontal overflow","symptom":"The emoji picker slid sideways and emojis didn't fit inside the box.","root_cause":"Unconstrained picker width allowed horizontal drift.","fix":"Constrained the picker to 340px / 8 columns with vertical-only scroll, verified inside the viewport.","session":"0b6b99f5"},{"app":"Finished.","category":"ui","title":"File menu dropdown rendered behind the toolbar","symptom":"Opening the File menu showed a glitch where the dropdown painted behind the editor toolbar.","root_cause":"The static .we-bar header created a stacking context, so the dropdown sat behind the later toolbar.","fix":"Elevated the header's stacking order so the File dropdown paints above the toolbar.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Freeze-count copy missing a separator","symptom":"The tracker copy read '3 freezes left this month keep it safe' with no separator.","root_cause":"","fix":"Changed copy to '{freezesLeft()} freeze(s) left this month · they keep your streak safe'.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Frozen blank screen while generating in 'Write it for me' modal","symptom":"The Write-it modal appeared frozen with no feedback while content was being generated.","root_cause":"No loading/thinking indicator was shown during generation.","fix":"Added an animated 'thinking' indicator so the screen no longer appears frozen.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Header logo circle-inside-a-circle","symptom":"The header logo rendered as a nested circle-inside-a-circle instead of the intended mark.","root_cause":"A second circle was nested inside the logo circle.","fix":"Rebuilt it as a single light-blue circle with a blue tick next to \"Finished.\"","session":"0b6b99f5"},{"app":"Finished.","category":"ui","title":"Home loads scrolled down with logo above the fold","symptom":"The home page loaded already scrolled down.","root_cause":"The home scrolls inside a height:100% container, so window.scrollTo(0,0) didn't reset it.","fix":"Added a proper scroll reset in App.tsx, with the fixed boot splash masking the reset.","session":"0f95b04e"},{"app":"Finished.","category":"ui","title":"Imprecise crop preview","symptom":"The crop preview implied the image wouldn't fit, yet the full image appeared once posted.","root_cause":"The crop preview didn't accurately reflect the final framing.","fix":"Fixed the preview to match output and added zoom in/out for timeline and profile photos.","session":"04df6fb8"},{"app":"Finished.","category":"ui","title":"Invalid hex color in boot splash CSS","symptom":"The boot splash background color was malformed.","root_cause":"A stray space made the hex invalid (#eaf0 fe).","fix":"Corrected the hex to #eaf0fe.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Launch-checklist checkmark rendered as a tiny square tick","symptom":"The launch checklist checkmark was a tiny tick in a square, not a big white tick in a circle like the logo.","root_cause":"","fix":"Replaced it with a clean big white check-circle (V1 and V2).","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Library star ratings render as huge dashed 'cylinder' boxes","symptom":"Book star ratings appeared as tall dashed boxes overlapping cards.","root_cause":"The empty-star span className 'empty' collided with the app's global .empty empty-state box (an 84x170px dashed placeholder).","fix":"Renamed/scoped the star glyph classes (.bt-empty at 18x18px) and added gradient book-cover thumbnails.","session":"bfc2eaa1"},{"app":"Finished.","category":"ui","title":"Light-hardcoded surfaces stranded dark text in dark mode","symptom":"The 'JUMP BACK IN' card and other surfaces stayed light in dark mode, leaving text unreadable.","root_cause":"Those surfaces had hardcoded light colors that ignored dark mode.","fix":"Made the JUMP BACK IN card and other surfaces dark with light text in dark mode.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Loading splash flickers in a self-heal reload loop","symptom":"The loading animation kept randomly reappearing.","root_cause":"With #root empty, the 10s self-heal timer fired location.reload(), re-showing the splash in a repeating loop.","fix":"Fixing the mount stopped the loop, and the boot script was simplified to one-shot recovery to remove the timer-vs-network flicker.","session":"0f95b04e"},{"app":"Finished.","category":"ui","title":"Logo dot not aligned inline with wordmark","symptom":"The brand logo dot sat out of line with the wordmark.","root_cause":"","fix":"Aligned the dot inline so dotTop equals brandTop.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Memoriser cut off on mobile","symptom":"The memoriser was cut off on mobile in Study.","root_cause":"","fix":"Fixed the mobile layout so the memoriser isn't clipped.","session":"879d06ee"},{"app":"Finished.","category":"ui","title":"Memoriser white-box text invisible in dark mode","symptom":"In the Memoriser, text in the white box was barely visible in dark mode.","root_cause":"","fix":"Revamped Memoriser dark-mode contrast so the box text is readable.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Milestones card layout shifts with content","symptom":"Milestones cards had buttons and progress bars in different positions depending on whether a card had a note.","root_cause":"Cards weren't equal height, so controls floated based on content.","fix":"Made cards equal height so progress bars and \"It happened!\" buttons sit in the same position.","session":"879d06ee"},{"app":"Finished.","category":"ui","title":"Mobile CSS rule leaking to desktop","symptom":"Layout overlap appeared on non-mobile viewports.","root_cause":"A mobile width:100%!important rule was declared outside its media query.","fix":"Scoped the mobile rule back inside its media query, resolving the overlap.","session":"0b6b99f5"},{"app":"Finished.","category":"ui","title":"Mobile sticky CTA overlap on booking page","symptom":"The mobile sticky CTA overlapped the Style/Edit buttons.","root_cause":"","fix":"Stacked the Style/Edit buttons above the sticky CTA to remove the overlap.","session":"6c59c3ad"},{"app":"Finished.","category":"ui","title":"Orphan word 'bed' wrapped alone in onboarding tour card","symptom":"The onboarding tour body text left the word 'bed' stranded on its own line.","root_cause":"","fix":"Applied text-wrap so the phrase wraps together (…on a walk or in bed.).","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Oversized /help and doc toolbar buttons","symptom":"The AI-artifact buttons were bulky full-width pills and the '/help' button was oversized and wrapped.","root_cause":"The buttons inherited global styles instead of being scoped to the toolbar.","fix":"Scoped dedicated classes (pj-doc-btn, flex-grow:0, content-sized) so buttons are tidy and match the toolbar scale.","session":"bfc2eaa1"},{"app":"Finished.","category":"ui","title":"Planner copy says morning for afternoon slots","symptom":"The planner said 'protected in the morning' even for afternoon slots.","root_cause":"Static copy not conditioned on slot time.","fix":"Made the copy match the slot's time of day.","session":"4237597d"},{"app":"Finished.","category":"ui","title":"Privacy/Terms links returned 404","symptom":"The Privacy and Terms redirects did not work.","root_cause":"","fix":"Fixed routing so the Privacy page renders at /?legal=privacy (404 resolved).","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Progress ring percentage unreadable in dark/Midnight theme","symptom":"The number inside the progress wheel and some text was hard to see at midnight/dark mode.","root_cause":"ProgressRing color was not theme-aware and tint dimming applied in dark mode.","fix":"Made ProgressRing theme-aware (white/readable % on every theme) and overrode the dark-mode tint dimming.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Rainbow splash animation keeps regressing","symptom":"The moving rainbow colour-splash first-load animation had reverted to static.","root_cause":"A git regression reintroduced the static splash.","fix":"Restored the animated splash and pinned/guarded it against regressing again.","session":"ec6dbc01"},{"app":"Finished.","category":"ui","title":"Re-picking the same story photo doesn't fire","symptom":"Selecting the same photo again for a story did nothing.","root_cause":"The file input wasn't reset, so re-selecting the same file didn't emit a change event.","fix":"Reset the story file input after selection (Stories.tsx).","session":"eae12f03"},{"app":"Finished.","category":"ui","title":"Screen Studio scenes stretched in resized window","symptom":"A half-sized window stretched scenes blurry/stocky instead of scaling cleanly.","root_cause":"Scenes were not constrained to a fixed contain-fit stage.","fix":"Made scenes a fixed 16:9 contain-fit stage so a resized window letterboxes.","session":"fd796bb1"},{"app":"Finished.","category":"ui","title":"Sign-in / sign-up screens cut off at the top","symptom":"The auth screens were clipped at the top on short viewports.","root_cause":"AuthGate used flexbox + overflow that clipped the top on short viewports.","fix":"Switched AuthGate to a robust block layout so the top is no longer cropped.","session":"8c8cbb86"},{"app":"Finished.","category":"ui","title":"Sign-in splash rendered broken","symptom":"The sign-in splash would have rendered broken.","root_cause":"CSS class-name collisions corrupted the splash styling.","fix":"Used unique class names and restored the original design (glowing ring, breathing logo, gradient bar).","session":"04df6fb8"},{"app":"Finished.","category":"ui","title":"Story black-flash before photo","symptom":"Opening a story showed a black screen before the photo loaded.","root_cause":"","fix":"Fixed the black-flash (verified by code, since a real story couldn't be driven locally).","session":"879d06ee"},{"app":"Finished.","category":"ui","title":"Time page horizontal scroll","symptom":"The Time page scrolled sideways.","root_cause":"Element width exceeded the card/viewport.","fix":"Applied a width fix so content fits within the card.","session":"04df6fb8"},{"app":"Finished.","category":"ui","title":"Timezone label shows underscores","symptom":"A timezone displayed as 'Port_of_Spain'.","root_cause":"The raw IANA identifier wasn't humanized.","fix":"Displayed 'Port of Spain' (underscores stripped).","session":"4237597d"},{"app":"Finished.","category":"ui","title":"Timezone picker truncates country names","symptom":"The timezone picker button truncated long country names.","root_cause":"The picker button layout ellipsized the country name.","fix":"Restructured the button to show the full country name on its own line.","session":"bfc2eaa1"},{"app":"Finished.","category":"ui","title":"Two bugs in the photo crop dialog","symptom":"The photo crop dialog misbehaved.","root_cause":"Two defects in CropModal.tsx (loop / blob-URL handling).","fix":"Fixed both CropModal.tsx bugs and committed.","session":"ec6dbc01"},{"app":"Finished.","category":"ui","title":"Typo in classic theme CSS","symptom":"A typo had slipped into the classic theme's CSS.","root_cause":"Malformed CSS in the classic theme.","fix":"Corrected the typo.","session":"f66ef7da"},{"app":"Finished.","category":"ui","title":"Ugly native prompt() used in Work feature","symptom":"The Work feature used a raw browser prompt() dialog.","root_cause":"","fix":"Replaced the prompt() with proper in-app UI (and added focus-stop celebration).","session":"8c8cbb86"},{"app":"Finished.","category":"other","title":"All AI silently ran on Gemini fallback instead of Claude","symptom":"AI features silently used the degraded Gemini fallback rather than Claude.","root_cause":"ANTHROPIC_API_KEY was stored in the Vault with a trailing space (unreadable), and edge functions read secrets from Deno.env rather than the Vault.","fix":"Created a read_vault_secret RPC that trims names (trim(name)=trim(secret_name)) so the key resolves and functions read the Vault.","session":"8c8cbb86"},{"app":"Finished.","category":"other","title":"Downloaded webm has infinite/no duration","symptom":"Downloaded recordings had no duration header and wouldn't seek.","root_cause":"Chrome writes no duration metadata for timesliced recordings.","fix":"Patch wall-clock, pause-aware duration into the file with fix-webm-duration so downloads seek.","session":"eae12f03"},{"app":"Finished.","category":"other","title":"fix-webm-duration dependency dropped from package.json","symptom":"The Cloudflare deploy would have broken even though local builds passed.","root_cause":"A concurrent session's commit had wiped `fix-webm-duration` out of package.json.","fix":"Restored the dependency in package.json.","session":"eae12f03"},{"app":"Finished.","category":"other","title":"Password-reset emails sent from an unverified domain","symptom":"The send-reset function would have its emails rejected by Resend.","root_cause":"The function sent from hi@hallalu.com, which is not the verified domain.","fix":"Changed the from address to hi@finished.hallalu.com (verified) with reply-to hi@hallalu.com.","session":"8c8cbb86"},{"app":"Finished.","category":"other","title":"Stale cached JavaScript made features appear broken","symptom":"Write templates, the Homework + button, and AI features all did nothing even though the code was correct.","root_cause":"The deployed app was serving stale JavaScript from the service worker cache.","fix":"Fixed the service worker so every deploy arrives instantly (with a one-time hard-refresh to clear the old bundle).","session":"0b6b99f5"},{"app":"Hallalu CRM","category":"security","title":"Business-plan /pitch gate bypassable via path tricks","symptom":"The gated /pitch content could be reached with two path tricks despite the gate.","root_cause":"The gate only guarded the route while the protected content still shipped in the static asset bundle.","fix":"Removed the protected content from the asset bundle entirely so the gate actually holds.","session":"9033ea59"},{"app":"Hallalu CRM","category":"security","title":"Owner email exposed client-side in admin.js","symptom":"The admin owner email was shipped in the client-side admin.js bundle.","root_cause":"The owner-email/admin check lived in client code instead of on the server.","fix":"Moved the owner email/admin check server-side.","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"data-loss","title":"Invoice builder wipes line items on every repaint","symptom":"'Add a line' did nothing and invoices could not be saved.","root_cause":"invoiceBuilder() re-initialised the line items on every repaint, wiping typed input.","fix":"Separated initialization from repaint so line items persist, and corrected the maths.","session":"9033ea59"},{"app":"Hallalu CRM","category":"crash","title":"/api/track throws TDZ from duplicate","symptom":"The `/api/track` endpoint threw a temporal-dead-zone error.","root_cause":"A leftover duplicate declaration.","fix":"Removed the duplicate; endpoint works.","session":"215ee275"},{"app":"Hallalu CRM","category":"crash","title":"Admin check crashes for signed-out users","symptom":"The app would crash for signed-out visitors.","root_cause":"`isAdminUser()` dereferenced a null account.","fix":"Added a null guard.","session":"215ee275"},{"app":"Hallalu CRM","category":"crash","title":"Hallucinated Stripe checkout APIs","symptom":"Checkout would have failed the instant real keys were added.","root_cause":"A previous session used non-existent Stripe APIs (a fake 'Dahlia' Stripe.js, `createEmbeddedCheckoutPage`, and a fabricated `API_VERSION='2026-07-29.dahlia'`).","fix":"Rewrote to the real Embedded Checkout API and correct version header (four fixes).","session":"215ee275"},{"app":"Hallalu CRM","category":"sync","title":"Stale HTML shell served from cache","symptom":"The browser kept serving a stale index.html, making fixes look broken for testers and real users.","root_cause":"The HTML shell was being cached even though versioned assets already handle caching.","fix":"Made the shell never cache so deploys are picked up immediately.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"Billing view shows outdated Solo/Studio/£19 pricing","symptom":"The billing/pricing view still displayed the old Solo/Studio tiers with a £19 price even for the free plan (the 'free 19 pounds' bug).","root_cause":"The billing view rendered a stale pricing model instead of the current flat tiers.","fix":"Rewrote the billing view to USD flat pricing with free=$0 and stripped the pricing promises.","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"logic","title":"Date handling produced the wrong year","symptom":"Goal/close dates resolved to the wrong year (e.g. 2024, and 'next Tuesday' became 2027).","root_cause":"Date arithmetic was wrong and the first guard only blocked past dates, pushing them to 2027.","fix":"Fixed date computation generally so relative dates resolve to the correct year.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"Dead route after creating a project while viewing a client","symptom":"Creating a project while viewing a client left the user on a dead route.","root_cause":"Navigation state after project creation resolved to an invalid route.","fix":"Corrected the post-creation navigation so it lands on a valid view.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"Delete actions silently do nothing","symptom":"Several delete controls appeared to work but deleted nothing.","root_cause":"The delete handlers were not wired to actually remove the item.","fix":"Fixed the deletes and added delete-confirmations everywhere.","session":"215ee275"},{"app":"Hallalu CRM","category":"logic","title":"Demo comms/leads didn't seed","symptom":"The demo's communications/leads didn't appear because they were never seeded.","root_cause":"Leads live in per-project data, but the demo seeded to st.leads (the wrong data path).","fix":"Fixed the demo seed path so demo leads/comms populate.","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"logic","title":"Demo shows wrong base currency","symptom":"The UK demo displayed USD instead of GBP.","root_cause":"A stale demo from before currency settings existed left USD hard-coded.","fix":"Set `st.settings.baseCurrency='GBP'` in decorateDemo.","session":"215ee275"},{"app":"Hallalu CRM","category":"logic","title":"Editing a lead can't set Google/Maps source","symptom":"Google/Maps couldn't be chosen when editing a lead, and demo leads were mislabeled call/email.","root_cause":"The edit form offered only 4 sources instead of the full source picker.","fix":"Switched the edit form to the full source picker and corrected the demo leads.","session":"215ee275"},{"app":"Hallalu CRM","category":"logic","title":"Hardcoded '3.1×' caption","symptom":"A '3.1×' caption was displayed as if computed but was hardcoded.","root_cause":"The multiplier was a static string rather than derived from data.","fix":"Corrected the caption for honesty rather than hardcoding it.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"Landing page silently redirects onboarded users to /app","symptom":"The deployed landing page at / was never visible to onboarded users because it silently bounced them to /app.","root_cause":"An onboarded-user redirect fired unconditionally at the root route.","fix":"Fixed the redirect (adding an ?app override) so the landing page is reachable.","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"logic","title":"Local 'pct' variable shadows global pct() function","symptom":"A percentage calculation misbehaved due to name collision.","root_cause":"A local variable named pct shadowed the global pct() function.","fix":"Renamed the shadowing local variable to remove the collision.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"NaN% reply rate and non-zero outreach on empty project","symptom":"An empty project showed NaN% for reply rate and a fresh project did not start its outreach count at 0.","root_cause":"Metrics divided by zero / lacked initialization for empty projects.","fix":"Removed the NaN and made a fresh project start outreach count at 0.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"Paste importer mis-parses co.uk domains","symptom":"Pasted leads with `.co.uk` sites and business domains were parsed wrong (domain treated as email).","root_cause":"TLD ordering matched `co` before `co.uk`, and business-domain-vs-email wasn't distinguished.","fix":"Fixed TLD ordering so `co.uk` matches first and separated business domain from email.","session":"215ee275"},{"app":"Hallalu CRM","category":"logic","title":"Paste importer treats a whole Google Maps paste as one lead","symptom":"Pasting Google Maps results imported only 'found 1 lead' and used the first line 'Sponsored' as the lead's name.","root_cause":"The importer split leads on blank lines, but Google Maps pastes have none, so the entire block parsed as a single lead.","fix":"Reworked the importer so a run-together paste splits into individual leads (via the AI-split path) instead of one block.","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"logic","title":"Phone-number parser misreads across lines","symptom":"Phone parsing failed on multi-line input and numbers with a leading parenthesis.","root_cause":"The phone regex crossed line boundaries and didn't allow a leading paren.","fix":"Rewrote the phone pattern to stay on one line and allow a leading paren.","session":"215ee275"},{"app":"Hallalu CRM","category":"logic","title":"Read-aloud reply and button do nothing","symptom":"The assistant's reply did not speak and the read-aloud button after the fact did nothing.","root_cause":"The speak-on-reply path and the manual read-aloud handler were both broken.","fix":"Fixed both halves so replies speak and the button works.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"Rolodex cards show fields with no way to enter them","symptom":"Contact cards displayed fields (e.g. in influencers) that had no corresponding input path.","root_cause":"Card display and the entry form were driven by different definitions.","fix":"Refactored so one schema drives both the card and the entry form.","session":"9033ea59"},{"app":"Hallalu CRM","category":"logic","title":"Trial→paid KPI shows NaN%","symptom":"The admin dashboard's 'Trial→paid' KPI rendered NaN%.","root_cause":"An operator-precedence error in the KPI calculation.","fix":"Corrected the precedence so the KPI computes a real percentage.","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"logic","title":"Worker chunking not byte-safe and header auth broken","symptom":"Worker request chunking and header-based auth were faulty.","root_cause":"Chunking split on characters rather than bytes and auth headers were mishandled.","fix":"Reworked the worker for byte-safe chunking and correct header auth.","session":"9033ea59"},{"app":"Hallalu CRM","category":"ui","title":"AI status stuck on 'Checking…' when API unreachable","symptom":"The AI buttons showed a perpetual 'Checking…' state and failed silently when the API was not reachable locally.","root_cause":"The unreachable-API case was not handled with a clear state.","fix":"Made the buttons report exactly what is missing instead of hanging or failing silently.","session":"9033ea59"},{"app":"Hallalu CRM","category":"ui","title":"Ava assistant invisible on mobile/dark","symptom":"The Ava assistant was white-on-white and unreadable in dark mode on phones.","root_cause":"Hard-coded #fff surfaces gave zero contrast on the hero stage, reply bubbles, and chips.","fix":"Fixed three contrast bugs and added a real mobile layout for the Ava page.","session":"215ee275"},{"app":"Hallalu CRM","category":"ui","title":"Broken Followers/Following/Photo grid","symptom":"The Followers/Following and Photo layout was mis-arranged.","root_cause":"The grid pairing was wrong.","fix":"Made Followers/Following a proper pair with Photo on its own row.","session":"215ee275"},{"app":"Hallalu CRM","category":"ui","title":"Clients-signed ring misaligned","symptom":"Ring numerals sat on different baselines and the 'clients signed' label was small and off-center.","root_cause":"Numerator/denominator and label were not aligned or sized correctly.","fix":"Aligned numerals on one baseline with a smaller denominator and centered/enlarged the label.","session":"9033ea59"},{"app":"Hallalu CRM","category":"ui","title":"Confetti persists under tab throttling","symptom":"Confetti outlived its welcome, lingering after it should have cleared.","root_cause":"The confetti animation was not cleaned up when the browser throttled the background tab.","fix":"Cleared the confetti so it no longer outlives its animation.","session":"9033ea59"},{"app":"Hallalu CRM","category":"ui","title":"Contact card not full width","symptom":"The rich-contact card rendered narrower than the container.","root_cause":"A helper constrained the card width.","fix":"Fixed the helper; card is now full width (689px).","session":"215ee275"},{"app":"Hallalu CRM","category":"ui","title":"Demo portraits mismatch names and gender","symptom":"Demo lead photos didn't match the leads' names or gender.","root_cause":"Photos used random `i.pravatar.cc/?u=` URLs.","fix":"Replaced with gender-inferred `randomuser.me` portraits via name-set heuristics.","session":"215ee275"},{"app":"Hallalu CRM","category":"ui","title":"Header buttons overflow, blocking Add to-do","symptom":"On a phone the 'Add to-do' button was clipped off the right edge, so users couldn't add a goal/to-do.","root_cause":"`.topbar` had no `flex-wrap`, so the action buttons overflowed on narrow screens.","fix":"Added flex-wrap to `.topbar`, fixing every view that uses the pattern.","session":"215ee275"},{"app":"Hallalu CRM","category":"ui","title":"Landing hero/aurora card invisible in dark mode","symptom":"In dark mode the hero/aurora card stayed light, making its text invisible.","root_cause":"`.hero` had a hardcoded background:#fff with no dark override, and as a stylesheet rule it wasn't caught by the inline-style dark-mode catch-all.","fix":"Added a dark-mode override for the .hero/aurora surface so its text is readable.","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"ui","title":"Microphone icon not centered in inputs","symptom":"The mic sat near the top line instead of centered in goal, to-do and other fields.","root_cause":"The mic was centered on the combined label+field height instead of just the field.","fix":"Re-centered every mic in the app so each measures 0px off-center.","session":"9033ea59"},{"app":"Hallalu CRM","category":"ui","title":"Tax page not findable in the nav","symptom":"The Tax page existed but users couldn't find or reach it.","root_cause":"Tax wasn't surfaced as a real, navigable page in the nav.","fix":"Made Tax a real, findable page in the nav (and expanded the spend categories).","session":"215ee275","source":"conversation-2026-08-10"},{"app":"Hallalu CRM","category":"ui","title":"Timezone widget falls off screen","symptom":"Swapping timezones pushed the widget off-screen at mid widths.","root_cause":"The timezone inputs didn't shrink or stack on narrow layouts.","fix":"Made the inputs shrinkable and stack earlier; verified no overflow at any width.","session":"215ee275"},{"app":"Hallalu CRM","category":"ui","title":"Unsized SVG renders oversized","symptom":"An SVG rendered giant on screen.","root_cause":"The SVG had no explicit dimensions.","fix":"Sized the SVG so it renders correctly.","session":"9033ea59"},{"app":"Hallalu CRM","category":"other","title":"ANTHROPIC_API_KEY saved with a leading space","symptom":"AI features silently did not work.","root_cause":"The secret was stored as ' ANTHROPIC_API_KEY' with a leading space, so env.ANTHROPIC_API_KEY was undefined.","fix":"Added a whitespace-tolerant secret() resolver so the key resolves regardless of stray whitespace.","session":"9033ea59"},{"app":"Hallalu CRM","category":"other","title":"Cloudflare env-var blocker (no worker script)","symptom":"Cloudflare rejected env vars with 'Variables cannot be added to a Worker that only has static assets'.","root_cause":"The Hallalu deployment had only static files and no worker script, so secrets could not attach.","fix":"Added a worker script so environment variables can be bound.","session":"9033ea59"},{"app":"Hallalu CRM","category":"other","title":"extras.js not loading","symptom":"The extras.js script failed to load.","root_cause":"","fix":"Corrected the loading so extras.js is included.","session":"9033ea59"},{"app":"Hallalu CRM","category":"other","title":"Legally wrong review-gating claims in shipped copy","symptom":"The app told users incorrect legal facts about review gating (e.g. 'illegal in the UK', 'FTC rule covers gating', a mischaracterised Yelp rule).","root_cause":"Four shipped legal claims and review-solicitation copy were inaccurate.","fix":"Corrected all four claims and replaced the generic 'reviews' source with three platform-specific rule sets.","session":"9033ea59"},{"app":"Stitchhooky","category":"security","title":"Co-stitch rooms and theme leak across accounts","symptom":"The next person on the device auto-joined your live co-stitch room and kept your theme.","root_cause":"Co-stitch room membership and appearance were not scoped per account.","fix":"Scoped co-stitch rooms and appearance per account so they no longer leak between users.","session":"bdf26458"},{"app":"Stitchhooky","category":"security","title":"Security headers silently ignored","symptom":"Security/CSP headers added in the worker did nothing.","root_cause":"Cloudflare serves static assets before the worker runs, so worker-set headers never applied.","fix":"Moved the headers to the proper `_headers` mechanism.","session":"236ae80d"},{"app":"Stitchhooky","category":"security","title":"Stored-XSS vectors in user content","symptom":"Multiple stored-XSS injection points, including an unescaped server value reaching an HTML attribute.","root_cause":"User/server values were rendered without escaping.","fix":"Escaped the values and closed all five stored-XSS vectors.","session":"236ae80d"},{"app":"Stitchhooky","category":"data-loss","title":"'Reset everything' resurrects data on reload","symptom":"Resetting everything did not stick; data came back on the next reload.","root_cause":"Reset left the rolling backup behind, and the loss-protection loader (which prefers whichever copy has more projects) resurrected everything.","fix":"Made reset also clear the rolling backup so it no longer resurrects.","session":"bdf26458"},{"app":"Stitchhooky","category":"data-loss","title":"Cross-account data leak on shared device","symptom":"A second person signing up on the same device saw the first user's projects and streak.","root_cause":"Accounts were stored in a single storage slot with no per-account scoping.","fix":"Scoped storage per account so a new user starts empty (proven: Bea sees zero projects).","session":"236ae80d"},{"app":"Stitchhooky","category":"data-loss","title":"Duplicate chart projects on every reload","symptom":"Reloading created a brand-new duplicate of the same chart project (three identically-named ones appeared).","root_cause":"`savedId` was never persisted, so each reload treated the chart as new.","fix":"Persisted savedId so a chart maps to one project.","session":"236ae80d"},{"app":"Stitchhooky","category":"data-loss","title":"Projects view wiped by a single corrupt save","symptom":"The projects view went blank with no warning.","root_cause":"`load()` silently fell back to empty defaults on any parse error, so one corrupt/truncated save destroyed everything.","fix":"Added backups and recovery (preserve the broken copy) and made each card render independently so one bad project can't blank the list.","session":"236ae80d"},{"app":"Stitchhooky","category":"data-loss","title":"Resize wipes the canvas artwork","symptom":"Resizing the grid erased the user's drawing.","root_cause":"The resize path cleared the canvas instead of preserving it.","fix":"Resize now preserves existing artwork.","session":"236ae80d"},{"app":"Stitchhooky","category":"data-loss","title":"Sign-up orphans or clobbers pre-account data","symptom":"Signing up could vanish pre-account projects or clobber an existing local store for a handle.","root_cause":"Pre-account projects were stored behind an ownerless key and sign-up did not adopt or protect them.","fix":"Pre-account projects are adopted by the first signer, and sign-up refuses a handle with an existing store and points to sign-in.","session":"bdf26458"},{"app":"Stitchhooky","category":"crash","title":"Boot crash from temporal dead zone","symptom":"The entire app died on first load with no console error.","root_cause":"`termKey` read `db` while `let db = load()` was still initializing (TDZ).","fix":"Reordered initialization so `db` exists before it is referenced.","session":"236ae80d"},{"app":"Stitchhooky","category":"crash","title":"HUD crash on second render","symptom":"Every count after the first would crash.","root_cause":"`renderCover` referenced an element its own rebuild had already destroyed.","fix":"Reworked renderCover to not reference the destroyed element.","session":"236ae80d"},{"app":"Stitchhooky","category":"crash","title":"LS_BAK temporal dead zone crash","symptom":"The app refused to boot.","root_cause":"`LS_BAK` was declared after `db=load()` ran, a use-before-initialisation TDZ.","fix":"Moved the declaration before it is used.","session":"236ae80d"},{"app":"Stitchhooky","category":"auth","title":"Passcode lockout with no escape hatch","symptom":"User was asked for a passcode they never set and could not get in.","root_cause":"A browser test left a lock flag in storage and there was no recovery path.","fix":"Added a forgot-passcode escape hatch (fixed three ways) and cleared the stray flag.","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Cell-click runs past end of row","symptom":"Clicking a cell could advance past the last stitch of a row into the next one.","root_cause":"No bound check on the click-to-advance path.","fix":"Clamped cell clicks to the current row's end.","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Chart collapses to a tiny thumbnail","symptom":"The chart shrank to a thumbnail inside a huge empty page card.","root_cause":"A scale calculation ran while the container was hidden (width read 0, scale went negative).","fix":"Removed transform-scaling and made the grid fill the page width with real cells.","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Chart-grow message flow miscounts","symptom":"The chart stage didn't repaint per message, the prompt offered to add skips instead of stitches, and it grew the wrong row.","root_cause":"Stage wasn't refreshed per message and the grow logic targeted a stale row index / wrong element type.","fix":"Repaint per message, name real stitches, and grow the correct row (verified 30→32).","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Community tab is a dead end","symptom":"Community refused with a toast telling the user to sign in via Settings.","root_cause":"It gated on a sign-in path that led nowhere.","fix":"Fixed the Community entry so it no longer dead-ends.","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Competing writers miscount home tiles","symptom":"The home tile still counted 13 stitches from a stale value.","root_cause":"Two ppMeta writers fought over the home tile count and the stale one won.","fix":"Consolidated to a single ppMeta writer.","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Dictation mic leak into counting view","symptom":"After dictating rows then hitting Save & start counting, speech kept appending rows to a stale draft instead of counting.","root_cause":"The mic stayed live with the dictation handler still attached when entering the counting studio.","fix":"Mic now hard-stops on entering the counting studio.","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Learn-to-read-charts modal silently fails","symptom":"Opening 'Learn to read charts' did nothing visible.","root_cause":"It opened a modal that silently failed.","fix":"Fixed the modal so the guide opens correctly.","session":"236ae80d"},{"app":"Stitchhooky","category":"logic","title":"Notation parser undercounts stitches ('7 vs 18')","symptom":"Stitch totals came out far too low, e.g. reporting 7 when it should be 18.","root_cause":"Two parser bugs — e.g. '6 sc in magic ring' collapsed to a single count, and many notation variants weren't recognized.","fix":"Parser overhaul plus a `normalizeNotation` that folds standing/stacked/foundation/post/Ntog/magic-ring variants into keys.","session":"7189645c"},{"app":"Stitchhooky","category":"ui","title":"Billing panel invisible at 0x0","symptom":"The billing panel had content but measured 0x0 and never showed.","root_cause":"A sizing rule collapsed the panel (and ten similar panels) to zero dimensions.","fix":"One layout rule fixed all eleven; billing now renders at 560x740.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"Dead hero photo on landing page","symptom":"The landing hero image 404'd, showing a broken tile.","root_cause":"It pointed at an expired Unsplash premium URL.","fix":"Swapped to a verified-200 photo and added a fallback that hides any tile whose image fails.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"Duplicate DOM ids after bento redesign","symptom":"Nine duplicate DOM ids made home-tile buttons behave unpredictably.","root_cause":"Replacing the home markup left the old tile row in place below the new bento.","fix":"Removed the leftover old tile row.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"iOS text too close to phone edge","symptom":"In the iOS simulator, words sat too close to the edge of the phone.","root_cause":"Horizontal padding was below Apple's 16pt margin guidance.","fix":"Raised horizontal padding to 22pt with the title at 27pt.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"Menu hidden behind next card","symptom":"The project menu rendered behind the following card instead of on top.","root_cause":"Z-index stacking-context bug.","fix":"Fixed the stacking so the menu layers above adjacent cards.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"Mic control runs off screen on real devices","symptom":"The mic control ran off the edge of the screen on real devices.","root_cause":"A missing/incorrect viewport meta tag.","fix":"Corrected the viewport meta tag.","session":"7189645c"},{"app":"Stitchhooky","category":"ui","title":"Mislabeled +n count bubble","symptom":"The +n increment bubble showed the wrong number.","root_cause":"","fix":"Corrected the bubble's label calculation.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"Settings button opened nothing","symptom":"The Settings control was genuinely broken and didn't open the panel.","root_cause":"`#settingsSheet` was the backdrop element, not the panel itself.","fix":"Corrected the settings sheet structure so the panel opens.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"Stale CSS rule squishes knit cells","symptom":"Knit grid cells rendered square despite correct code.","root_cause":"A leftover `.gm-cell` CSS rule from the old grid maker silently overrode the new knit geometry.","fix":"Removed the stale rule so per-craft geometry applies.","session":"236ae80d"},{"app":"Stitchhooky","category":"ui","title":"Tile colour clashes with theme accent","symptom":"Tile colours (e.g. purple) did not match the theme the user picked.","root_cause":"Tile background wasn't bound to the chosen accent colour.","fix":"Tiles now follow the theme's colour and each tile background is picker-controlled.","session":"236ae80d"},{"app":"Stitchhooky","category":"other","title":"CSP blocks YouTube thumbnails and embeds","symptom":"The new CSP would have broken YouTube thumbnails and video embeds.","root_cause":"The content-security-policy was too strict for the embed resources.","fix":"Widened the CSP and re-verified zero blocked resources.","session":"236ae80d"},{"app":"Stitchhooky","category":"other","title":"Users served stale app version","symptom":"Returning users silently ran old JavaScript/HTML, making just-added features look missing.","root_cause":"The `?v=` cache-busters weren't regenerated and HTML wasn't revalidated at the cache layer.","fix":"Bumped/regenerated the `?v=` stamps and made HTML always revalidate.","session":"236ae80d"},{"app":"Hopefil","category":"security","title":"Proprietary pricing/cost information leaking in the app","symptom":"The app displayed confidential proprietary information such as per-credit cost and margins.","root_cause":"Internal-economics copy and figures were exposed in the shipped bundle.","fix":"Audited and fixed all five leaks (e.g. margin language replaced) and verified a clean leak-scan.","session":"b8ffaddc"},{"app":"Hopefil","category":"sync","title":"Preview freezes at an outdated state","symptom":"The visual preview froze at an outdated state (preview sync bug).","root_cause":"Generators ran client-side without a guard against stale async responses.","fix":"Moved generators to the worker with a cached, stale-response-guarded async shim and a 350ms hue-slider debounce.","session":"f5cf1ca6"},{"app":"Hopefil","category":"race","title":"Stale-closure loses rapid goal/checklist clicks","symptom":"Rapid goal clicks used stale state (Income got overwritten by Community) and rapid checklist clicks registered only 1 of 3.","root_cause":"Handlers captured stale state in a closure instead of using the latest value.","fix":"Switched to a functional updater/toggle so each rapid click registers.","session":"b8ffaddc"},{"app":"Hopefil","category":"logic","title":"Dead landing CTA buttons","symptom":"Landing page CTA buttons did nothing (user-blocking).","root_cause":"The 'Start building' nav pill was a plain #start anchor with no action wired.","fix":"Made the nav pill a real action, made the empty-input nudge unmissable, and un-crowded mobile nav.","session":"f5cf1ca6"},{"app":"Hopefil","category":"logic","title":"Generated files stamped with year 1996","symptom":"Generated files were timestamped 1996 instead of 2026.","root_cause":"A wrong timestamp base in the file generator.","fix":"Corrected the timestamp so files stamp the current year.","session":"b8ffaddc"},{"app":"Hopefil","category":"logic","title":"Greeting rotation regression","symptom":"The per-visit greeting rotation regressed during a change.","root_cause":"A regression introduced while editing the greeting logic.","fix":"Caught and fixed the regression so greetings rotate per visit from the pool.","session":"b8ffaddc"},{"app":"Hopefil","category":"logic","title":"Kotlin extension properties fail through fully-qualified chains","symptom":"Every exported Kotlin app would fail to compile on certain property access.","root_cause":"The generator template emitted Kotlin extension properties resolved through fully-qualified chains, which Kotlin cannot resolve.","fix":"Fixed the generator template (and live generator) so extension properties resolve correctly.","session":"f5cf1ca6"},{"app":"Hopefil","category":"ui","title":"Android FAB not to Material 3 spec","symptom":"The Android floating action button had the wrong spec and clearance.","root_cause":"FAB sizing/clearance did not follow M3.","fix":"Rebuilt the Android FAB to M3 spec with correct clearance.","session":"f5cf1ca6"},{"app":"Hopefil","category":"ui","title":"Barber app shows a wrong photo","symptom":"The barber demo app rendered a wrong/mismatched photo.","root_cause":"An ambiguous/mismatched image was used at hero crop.","fix":"Rendered mesh-art plus gradient-initial 'MR' avatars instead of the wrong photo.","session":"f5cf1ca6"},{"app":"Hopefil","category":"ui","title":"Composer bar shows giant gradient pills","symptom":"The dashboard composer bar rendered giant gradient pills instead of a compact input/mic/button.","root_cause":"It inherited the landing hero styles (a CSS inheritance bug).","fix":"Scoped the composer styles to input-first, 40px mic at its side, compact 96px 'New app'.","session":"b8ffaddc"},{"app":"Hopefil","category":"ui","title":"Desktop/Mac/Web preview renders as a banner and single column","symptom":"Desktop, Mac and Web previews showed a lone phone column / banner and one name instead of a full-screen multi-column layout.","root_cause":"One CSS keyword prevented auto-fit multi-column from firing, and a 118px card floor collapsed grids to one column.","fix":"Made columns follow measured pane width via auto-fit and lowered the card floor to 70px for genuine multi-column desktop layouts.","session":"f5cf1ca6"},{"app":"Hopefil","category":"ui","title":"Empty-prompt CTA silently does nothing","symptom":"Clicking 'New app' or 'Start building' with an empty prompt box did nothing — no builder, error, or feedback.","root_cause":"The `if (!text) return` guard in `start()` bailed silently.","fix":"Empty click now focuses the input, shakes the prompt bar, and highlights the hint.","session":"b00cd1e8"},{"app":"Hopefil","category":"ui","title":"Mobile nav wrap and file-list truncation","symptom":"In the narrow panel view the mobile nav wrapped and the file list truncated.","root_cause":"Layout did not handle the narrow width.","fix":"Fixed the mobile nav wrap and file-list truncation.","session":"b8ffaddc"},{"app":"Hopefil","category":"ui","title":"Pitch deck low contrast and overlapping footnotes","symptom":"Grey text on slides 7/8/9 was hard to read and footnotes overlapped the content.","root_cause":"Dim text colors and footnotes that overlaid rather than flowed.","fix":"Brightened the grey text, made footnotes flow below the legend, and auto-faded the arrow hint after 5s.","session":"b8ffaddc"},{"app":"Hopefil","category":"ui","title":"Pitch deck nav arrows un-positioned and wrong start slide","symptom":"The pitch deck did not start at slide 1 and the nav arrows were not centered at the sides.","root_cause":"An 'all:unset' declared after 'position:fixed' un-positioned the arrows (CSS order matters).","fix":"Reordered the CSS so arrows are centered and the deck starts at slide 1.","session":"b8ffaddc"},{"app":"Hopefil","category":"ui","title":"READY tiles stay dark on the light theme","symptom":"Some cards showed as black while others were white (READY tiles dark on the light theme).","root_cause":"The theme token fix missed the dark .card-veil overlay.","fix":"Applied the token fix to the .card-veil overlay so tiles match the theme.","session":"f5cf1ca6"},{"app":"Hopefil","category":"ui","title":"Review-phase placeholder shows 'Building…' while awaiting approval","symptom":"The review phase displayed a 'Building…' placeholder while it was actually awaiting user approval.","root_cause":"The placeholder text did not distinguish the awaiting-approval state.","fix":"Corrected the review-phase placeholder to reflect the awaiting-approval state.","session":"b8ffaddc"},{"app":"Hopefil","category":"ui","title":"Six preview render/display complaints","symptom":"Category leak on a booking app, barber photo reading as a living room, toy-like toggle proportions, tab-bar labels wrapping, and settings labels ellipsizing.","root_cause":"Multiple control-spec and layout issues across preview rendering.","fix":"Fixed all six in code to researched control specs and encoded each as a rule in BUILD.md.","session":"f5cf1ca6"},{"app":"Hopefil","category":"ui","title":"Stat numbers spilling over and jumbled","symptom":"Numbers in stat chips spilled over and looked jumbled.","root_cause":"Stat chips were not wrap-proof.","fix":"Rebuilt the stat chips as wrap-proof primitives and recorded the rule as law.","session":"f5cf1ca6"},{"app":"Hopefil","category":"ui","title":"Wrong hue value on the render wall","symptom":"The render wall used a wrong hue.","root_cause":"A hue value of 30 was incorrect.","fix":"Set the warm color 0xFFD38C45 so all three render modes and dark mode render correctly.","session":"b8ffaddc"},{"app":"Hopefil","category":"other","title":"Dev-server port mismatch in launch.json","symptom":"The preview tooling couldn't attach to the dev server.","root_cause":"The dev server binds 5197 but launch.json specified 5199.","fix":"Corrected the port in launch.json.","session":"b00cd1e8"},{"app":"Hopefil","category":"other","title":"Exported Android build fails: missing gradle.properties useAndroidX","symptom":"The exported Android project failed its first-run compile in the farm.","root_cause":"gradle.properties lacked android.useAndroidX=true.","fix":"Added the one-line android.useAndroidX=true to gradle.properties and rebuilt.","session":"f5cf1ca6"},{"app":"Budget LevelUp","category":"security","title":"TOTP QR service leaked 2FA secret","symptom":"Enabling 2FA sent the TOTP secret to a third-party QR service.","root_cause":"The QR code was generated via an external service, exposing the secret.","fix":"Removed the external QR call and replaced it with private manual key entry.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"data-loss","title":"Excel month selector wrote to the wrong cell","symptom":"Changing the month in the Social Tracker workbook did not affect the formulas' results.","root_cause":"The month selector wrote to a cell the formulas never read.","fix":"Pointed the selector at the cell the formulas read and re-verified 0 error cells.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"data-loss","title":"note() call destroyed the month selector cell","symptom":"A merged note silently wiped the month selector cell in the workbook.","root_cause":"A note() call wrote a merged cell over the month selector.","fix":"Reworked the merge so the note no longer overwrites the month cell.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"crash","title":"Celebrate tab crashes on saved payment card","symptom":"The Celebrate tab crashed for a fresh guest and whenever a payment card existed.","root_cause":"S.cards was shared by both the card register and celebration gallery, so Celebrate read .copy.headline off a payment card.","fix":"Moved celebration cards to their own S.celebCards key and made the gallery defensive against malformed entries.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"auth","title":"Vault C1 brute-force / no per-account retrieval token","symptom":"The encrypted vault was brute-forceable and lacked per-account isolation.","root_cause":"No per-account retrieval token; a shared retrieval path was guessable.","fix":"Added a per-account retrieval token with a dual-read migration (legacy accounts sign in with zero lockout), first mitigated by a rate limit.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"logic","title":"Broken social link handling","symptom":"Pasting a social URL produced a dead link, and bad image URLs showed a broken icon.","root_cause":"Links without an https:// prefix and junk text were not normalized, and image errors were unhandled.","fix":"Auto-prefix bare URLs to working links, reject junk text, and degrade broken images to a placeholder.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"logic","title":"Invoice button silently added an investment","symptom":"Clicking the Business invoice button silently created an investment instead.","root_cause":"The invoice button shared a DOM element id with the Investments add-holding button.","fix":"Gave the buttons unique ids and hardened the wiring; verified invoices and investments now act independently.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"logic","title":"Merged-cell collision in pillars card","symptom":"Merged cells in the pillars card collided, corrupting the layout/values.","root_cause":"Overlapping merged-cell ranges in the pillars card.","fix":"Resolved the merged-cell collision and re-verified.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"logic","title":"toISOString() shifted calendar events a day early","symptom":"Calendar events appeared one day earlier than the chosen date.","root_cause":"toISOString() applied a UTC timezone shift to local dates.","fix":"Avoided the UTC conversion so dates stay on the intended day.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"logic","title":"Untranslated card titles and chart labels","symptom":"Card titles and chart row labels stayed in English after switching language.","root_cause":"Those strings were missed by the localization pass.","fix":"Translated the remaining titles/labels and redeployed.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"ui","title":"Calendar alignment assignment typo","symptom":"The calendar rendered with broken alignment.","root_cause":"A typo in the alignment assignment for the calendar.","fix":"Corrected the alignment assignment in review.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"ui","title":"Jumbled platform-mix card in summary band","symptom":"The platform-mix card layout appeared jumbled in the planner summary band.","root_cause":"","fix":"Reworked the platform-mix card layout in the summary band.","session":"a1ee807a"},{"app":"Budget LevelUp","category":"other","title":"recalc.py crashed on Python 3.9","symptom":"The recalc verification script threw a TypeError.","root_cause":"ignore_cleanup_errors is unsupported on Python 3.9.","fix":"Replaced it with an AppleScript-driven Excel recalc harness.","session":"a1ee807a"},{"app":"Breadcrumb","category":"security","title":"+feature truncation swallows text and skips redaction","symptom":"The `+feature` command read a fixed 60 characters, swallowing the rest of the sentence, and the swallowed text bypassed redaction (secret-leak risk).","root_cause":"A fixed 60-char read plus the swallowed remainder never passing through the redactor.","fix":"Read the full text and route it through redaction, using exact-match so tokens like `#bug` can't be swallowed.","session":"1d8ee789"},{"app":"Breadcrumb","category":"auth","title":"Recovery codes hashed inconsistently","symptom":"Valid recovery codes could fail because hashing was inconsistent.","root_cause":"Recovery codes were hashed inconsistently between generation and verification.","fix":"Hash recovery codes consistently.","session":"1d8ee789"},{"app":"Breadcrumb","category":"sync","title":"Docs not synced","symptom":"Docs weren't reliably persisted/synced.","root_cause":"There was no synced docs store.","fix":"Added a proper synced `docs` table and fixed the size cap.","session":"1d8ee789"},{"app":"Breadcrumb","category":"logic","title":"`>cursor` builder-switch token silently discarded","symptom":"A `>cursor` builder switch inside a captured prompt was silently dropped.","root_cause":"An undefined template-literal segment (rendering as `undefined}`) discarded the `>cursor` token.","fix":"Fixed the parsing so the builder-switch token is preserved.","session":"1d8ee789","source":"conversation-2026-08-10"},{"app":"Breadcrumb","category":"logic","title":"Capture-bar quick chips don't update the prompt placeholder","symptom":"Clicking a quick builder chip in the capture bar didn't update the 'What did you just ask X for?' message or switch the builder; only opening 'More' did.","root_cause":"The quick chips lacked the handler that updates the placeholder and sets the active builder.","fix":"Added selectCaptureBuilder() so a chip updates the placeholder in place (preserving typed text) and sets the builder.","session":"1d8ee789","source":"conversation-2026-08-10"},{"app":"Breadcrumb","category":"logic","title":"Inconsistent text normalization","symptom":"Normalization behaved inconsistently across paths.","root_cause":"Normalization logic differed between code paths.","fix":"Made normalization consistent.","session":"1d8ee789"},{"app":"Breadcrumb","category":"logic","title":"Settings card can't read subscription periodEnd","symptom":"The settings card read periodEnd but received nothing.","root_cause":"publicUser didn't expose periodEnd.","fix":"Exposed periodEnd on publicUser so the settings card can show the subscription period.","session":"1d8ee789","source":"conversation-2026-08-10"},{"app":"Breadcrumb","category":"logic","title":"Trail outcome filter is a dead control","symptom":"Clicking the trail's outcome filter (All/worked/almost/didn't-work) did nothing.","root_cause":"`trail-filter` had no handler at all.","fix":"Wired the outcome filter so it actually filters the trail.","session":"1d8ee789","source":"conversation-2026-08-10"},{"app":"Breadcrumb","category":"ui","title":"Forget-device button lacked a confirmation","symptom":"The forget-this-device shortcut (a trash/X button) executed with no confirmation, against the every-destructive-action-confirms rule.","root_cause":"The button had no confirm dialog.","fix":"Added a confirmation before forgetting the device.","session":"1d8ee789","source":"conversation-2026-08-10"},{"app":"Breadcrumb","category":"ui","title":"Insights dashboard grid misrendered","symptom":"The Insights dashboard's 4-column stat-tile row (plus donuts, bars, heatmap and comparison) didn't lay out correctly.","root_cause":"An Insights grid class bug broke the layout.","fix":"Fixed the grid class (v24) so the stat-tile row and charts render properly.","session":"1d8ee789","source":"conversation-2026-08-10"},{"app":"Breadcrumb","category":"ui","title":"srcdoc iframe thumbnails render blank","symptom":"Prompt thumbnails showed blank.","root_cause":"`loading=\"lazy\"` on srcdoc iframes plus a `height:200%` that never resolved against an aspect-ratio height.","fix":"Removed lazy loading, set srcdoc as a property, and deferred one frame so thumbnails render.","session":"1d8ee789"},{"app":"Breadcrumb","category":"other","title":"i18n script not included in index.html","symptom":"The i18n script wasn't loaded, so localization wouldn't run.","root_cause":"The i18n script tag was never added to index.html (only security.js had a bumped version).","fix":"Added the i18n script to index.html.","session":"1d8ee789","source":"conversation-2026-08-10"},{"app":"Planner Studio","category":"crash","title":"arguments.callee ReferenceError breaks task ticking","symptom":"To-do items wouldn't tick off; the first render's refresh callback threw silently.","root_cause":"`arguments.callee` used inside an arrow function throws a ReferenceError in strict mode.","fix":"Replaced it with a hoisted `refreshTasks` declaration.","session":"2d2c2119"},{"app":"Planner Studio","category":"crash","title":"Gradient theme crash from id mismatch","symptom":"The gradient theme never applied because its checks never matched.","root_cause":"Theme objects used `id:'grad'` but code checked `t.grad`.","fix":"Changed all references to `t.id === 'grad'`.","session":"2d2c2119"},{"app":"Planner Studio","category":"sync","title":"Service worker cached a 404 for a later-added file","symptom":"A vendor file added after first cache stayed permanently broken.","root_cause":"The service worker had cached a 404 from before the file existed and kept serving it.","fix":"Fixed the worker/caching path so all vendor files serve correctly.","session":"2d2c2119"},{"app":"Planner Studio","category":"logic","title":"Monochrome theme hue not updating","symptom":"Changing the mono hue had no effect.","root_cause":"","fix":"Fixed the mono hue to update.","session":"2d2c2119"},{"app":"Planner Studio","category":"logic","title":"Schedule data-model change regression","symptom":"After changing schedule data from string to an object, consumers still reading it as a string could break (calm mode, week view, search, celebrate cards).","root_cause":"Schedule model changed from string to `{t,c,done,note}` but readers of `D.sched[h]` weren't updated.","fix":"Updated the consumers to the new object model.","session":"2d2c2119"},{"app":"Planner Studio","category":"ui","title":"'0/0' task counter not updating live","symptom":"The task counter stayed at 0/0 instead of reflecting progress.","root_cause":"The counter wasn't refreshed after a toggle.","fix":"Made the counter update live.","session":"2d2c2119"},{"app":"Planner Studio","category":"ui","title":"Both modal dialogs render on load","symptom":"Two modal sheets both showed on first boot.","root_cause":"A `display:grid` CSS rule overrode the `hidden` attribute.","fix":"Corrected the CSS so hidden sheets stay hidden and the app boots to Today.","session":"2d2c2119"},{"app":"Planner Studio","category":"ui","title":"Duplicate calmBtn DOM id","symptom":"Two elements shared the `calmBtn` id.","root_cause":"The Today hero button reused an existing element id.","fix":"Renamed the Today hero button to `calmStart`.","session":"2d2c2119"},{"app":"Planner Studio","category":"ui","title":"Kawaii theme buttons unreadable","symptom":"Kawaii-theme buttons used white ink that failed contrast.","root_cause":"Light ink on light buttons.","fix":"Applied dark ink to kawaii buttons per the contrast research.","session":"2d2c2119"},{"app":"Planner Studio","category":"ui","title":"Meal grid misaligns below 860px","symptom":"The meal grid broke below 860px, silently misaligning days against meals.","root_cause":"Responsive grid layout failed under the 860px breakpoint.","fix":"Fixed the grid so days and meals stay aligned at narrow widths.","session":"2d2c2119"},{"app":"Planner Studio","category":"ui","title":"PDF cover text overlapping","symptom":"Cover words overlaid each other on the planner's first page/PDF cover.","root_cause":"Insufficient vertical spacing in the cover layout.","fix":"Fixed spacing between title, subtitle and year, and rebuilt all 12 PDFs.","session":"2d2c2119"},{"app":"Prompt Vault","category":"logic","title":"Beauty-mark descriptor produced a lip piercing","symptom":"Subject prompts rendered an unwanted lip piercing.","root_cause":"The phrase 'beauty mark above the left lip' near the mouth was interpreted as a piercing.","fix":"Changed subject descriptors to freckles/cheekbones/dimples, never a mark near the lips.","session":"5cfb6aee"},{"app":"Prompt Vault","category":"logic","title":"Ebook hyperlinks not rendered inline","symptom":"PDF link annotations weren't appearing, undercutting the 'fully hyperlinked' claim.","root_cause":"reportlab requires links to be drawn inline, which the generator wasn't doing.","fix":"Drew the links inline so the ebook is fully hyperlinked (27,993 link annotations verified).","session":"2d2c2119"},{"app":"Prompt Vault","category":"logic","title":"Mirror-reversed, garbled on-image timestamp","symptom":"Generated mirror-selfie images produced a flipped, broken timestamp.","root_cause":"Prompts let text render inside the mirror, so it came out reversed.","fix":"Added a text-overlay clause telling the model to render on-image text as a flat, upright overlay, never inside the mirror.","session":"5cfb6aee"},{"app":"Prompt Vault","category":"logic","title":"Prompts produced generic, non-model subjects","symptom":"Users got a generic subject instead of a model-grade one.","root_cause":"Only 3 of 1,480 mega prompts demanded a beautiful/model-grade subject.","fix":"Added a subject-lock/beauty-floor transform across all mega prompts.","session":"5cfb6aee"},{"app":"Prompt Vault","category":"logic","title":"Search returned zero results","symptom":"Search returned 0 results despite the 'find anything you've ever written' claim.","root_cause":"Notes, Books and Content were added without extending the search index.","fix":"Extended the search index to include the new content types.","session":"2d2c2119"},{"app":"Prompt Vault","category":"logic","title":"Text-fix clause injected inside the --oref placeholder","symptom":"The orientation-fix clause landed inside the [your model … --oref …] placeholder, breaking it.","root_cause":"The build transform treated --oref as a trailing parameter when inserting the clause.","fix":"Placed the orientation-fix clause at the end so the placeholder stays intact.","session":"5cfb6aee"},{"app":"Prompt Vault","category":"ui","title":"Transparent card background over content","symptom":"A card used a transparent background causing a visual glitch.","root_cause":"The background was not opaque/theme-aware.","fix":"Switched it to an opaque, theme-aware background.","session":"5cfb6aee"},{"app":"Prompt Vault","category":"other","title":"Incorrect flat '696 pages' label","symptom":"All files were labeled '696 pages' but the 2028 files are actually 697-701 pages.","root_cause":"A hardcoded page count ignored leap-year and week-alignment variation.","fix":"Corrected the per-year page-count labels.","session":"2d2c2119"},{"app":"Hello Baby","category":"security","title":"Weak recovery keys and unescaped attribute sinks","symptom":"Recovery keys were brute-forceable and some attributes were unescaped (XSS risk now that spaces are shared).","root_cause":"Recovery keys used weak `Math.random()`; attribute sinks were unescaped.","fix":"Strengthened recovery-key generation and escaped the attribute sinks, in Hello Baby and the same inherited code in Happy Travel.","session":"2d2c2119"},{"app":"Hello Baby","category":"data-loss","title":"Entities deleted without confirmation","symptom":"Five places deleted data without asking.","root_cause":"Missing delete-confirmation guards.","fix":"Added delete confirmations to all five places plus broader edit-everything support.","session":"2d2c2119"},{"app":"Hello Baby","category":"logic","title":"Arrival without due date routed to wrong screen","symptom":"A baby with no due date fell into the wrong screen.","root_cause":"Ordering logic mishandled a missing due date.","fix":"Route arrival-without-due-date straight to the correct age-based screen (e.g. '3RD BIRTHDAY').","session":"2d2c2119"},{"app":"Hello Baby","category":"ui","title":"App showed Happy Travel nav instead of baby app","symptom":"The brand said Hello Baby but the nav showed Happy Travel's 'My Trips / Journey / Passport'.","root_cause":"Leftover Happy Travel app code from the fork.","fix":"Restored the correct baby nav (Home / Events / Babymoon & Trips / Milestones).","session":"2d2c2119"},{"app":"Hello Baby","category":"ui","title":"Blurry, hard-to-read wording","symptom":"Text looked fuzzy and dark numbers collided with the dark silhouette.","root_cause":"A soft glow added for legibility made text fuzzy, and dark-on-dark clashed.","fix":"Removed the glow and fixed the number/silhouette contrast.","session":"2d2c2119"},{"app":"Hello Baby","category":"ui","title":"Budget edits buried and unfindable","symptom":"The user couldn't find budget edits because they were buried at the bottom of the Events tab.","root_cause":"Budget was nested inside Events instead of surfaced.","fix":"Promoted Budget to its own standalone tab and added a hamburger menu.","session":"2d2c2119"},{"app":"Hello Baby","category":"ui","title":"Literal \\n rendering escaped","symptom":"A literal `\\n` was showing instead of a line break.","root_cause":"Incorrect newline escaping.","fix":"Corrected the escaping.","session":"2d2c2119"},{"app":"Wedding Planner","category":"crash","title":"openpyxl StyleProxy crash on font copy","symptom":"xlsx generation failed when copying fonts.","root_cause":"Assigning `.font = ws[cell].font` uses an unhashable StyleProxy.","fix":"Apply named fonts conditionally instead of copying the StyleProxy.","session":"2d2c2119"},{"app":"Wedding Planner","category":"ui","title":"Analysis donut rendered incorrectly","symptom":"The analysis donut chart displayed wrong.","root_cause":"","fix":"Fixed the donut rendering.","session":"2d2c2119"},{"app":"Wedding Planner","category":"ui","title":"Duplicated block in wedding-party view","symptom":"The wedding party showed a duplicated half-block.","root_cause":"Duplicated code lines in wed.js (caught by node --check).","fix":"Removed the duplicate lines and converted the cramped table to readable cards + editor.","session":"2d2c2119"},{"app":"Wedding Planner","category":"ui","title":"Filler images not loading (naturalWidth 0)","symptom":"Filler/Unsplash images failed to load (naturalWidth 0).","root_cause":"Image URL handling prevented the images from loading.","fix":"Store the image URL directly and let the `<img>` element load it.","session":"2d2c2119"},{"app":"Wedding Planner","category":"ui","title":"Seating flow dead-ends after adding a table","symptom":"Adding a table left an empty table with no way forward.","root_cause":"There was no way to seat guests into a newly added table.","fix":"Added capacity meters, per-table '+ Seat a guest here' dropdowns, meal tallies, auto-seat and a 'still to seat' pool.","session":"2d2c2119"},{"app":"Wedding Planner","category":"other","title":"Nested git repo leaked into monorepo commit","symptom":"A wedding-planner gitlink was committed into the BUDGETLEVELUP monorepo.","root_cause":"wedding-planner has its own repo and was added as a gitlink.","fix":"Removed the leaked gitlink from the monorepo commit.","session":"a1ee807a"},{"app":"Ever After","category":"sync","title":"Service worker pins returning users to old build","symptom":"Returning visitors saw stale builds — old splash rings, white space under content, and a mis-sized rainbow ring.","root_cause":"The root `/` navigation was served cache-first, pinning users to a stale index.html.","fix":"Made navigations network-first and bumped the cache version to purge stale caches; the identical bug was also fixed in Planner Studio.","session":"2d2c2119"},{"app":"Ever After","category":"race","title":"Join boot race gives joiners the wrong cloud key","symptom":"Users joining a shared space were given their own cloud key and shown the wrong 'your key' popup.","root_cause":"Two boot-time races in the share/join flow.","fix":"Fixed the boot races so joiners use the correct shared key and popup.","session":"2d2c2119"},{"app":"Ever After","category":"ui","title":"Choose-a-photo box shows literal ${imgIconSVG(34)}","symptom":"The photo-picker box displayed the literal text `${imgIconSVG(34)}` (plus a fallback clock glyph) instead of an image icon.","root_cause":"`imgIconSVG(34)` was inside a single-quoted string (wed-data.js:15), so it wasn't evaluated.","fix":"Broke out of the single-quoted string to call imgIconSVG so a real image icon renders.","session":"2d2c2119"},{"app":"Ever After","category":"ui","title":"tvPhoto icon printed as literal text","symptom":"`${IMG_ICON(32)}` showed as literal text in tvPhoto instead of the icon.","root_cause":"The placeholder sat inside a single-quoted string, so it wasn't interpolated.","fix":"Built the string with concatenation so IMG_ICON is actually called.","session":"2d2c2119"},{"app":"Ever After","category":"other","title":"Corrupted emoji entry","symptom":"One corrupted emoji entry had slipped into the data.","root_cause":"Malformed emoji entry.","fix":"Corrected the emoji entry.","session":"2d2c2119"},{"app":"Listing Lab Pro","category":"security","title":"SSRF via /api/open and /api/fetch","symptom":"Server-side fetch endpoints could be pointed at arbitrary internal hosts.","root_cause":"The browser-open/fetch paths had no host allowlist.","fix":"Added a host allowlist to /api/open and /api/fetch in worker.js.","session":"a1ee807a"},{"app":"Listing Lab Pro","category":"security","title":"XSS in Listing Lab render path","symptom":"Untrusted content could execute script in Listing Lab.","root_cause":"Unsanitized input rendered into the page.","fix":"Applied output sanitization to close the XSS vector.","session":"a1ee807a"},{"app":"Listing Lab Pro","category":"logic","title":"AI misattributed quotes between listings","symptom":"The analyzer attributed one listing's quote to a different listing.","root_cause":"The prompt allowed cross-listing bleed when run on many listings.","fix":"Tightened the prompt and re-ran 10 listings to confirm correct attribution.","session":"a1ee807a"},{"app":"Listing Lab Pro","category":"logic","title":"Digit confusion when reading listing images","symptom":"Digits were misread from images.","root_cause":"No image preprocessing before digit recognition.","fix":"Added proper image preprocessing and generalized the digit-confusion fix.","session":"2d2c2119"},{"app":"Listing Lab Pro","category":"logic","title":"Scraper pulled related-item ads and foreign shops","symptom":"Analyses were polluted by related-item ads and other shops' listings, which would have produced wrong results.","root_cause":"The scraper didn't filter related-item ads or restrict to the listing's own shop.","fix":"Filter out related-item ads and keep only the dominant shop, detected via the shop ID embedded in image URLs.","session":"2d2c2119"},{"app":"Social LevelUp","category":"security","title":"XSS via paste into contenteditable notes editor","symptom":"Pasting HTML into the notes editor could inject script.","root_cause":"Contenteditable paste was unsanitized (same class as Trix CVE-2024-53847).","fix":"Sanitized pasted content in the notes editor and applied the same fix to the budget app's notes editor.","session":"a1ee807a"},{"app":"Social LevelUp","category":"crash","title":"cur0 is not defined crash on post save","symptom":"Saving a post with income entered crashed the app.","root_cause":"An undeclared identifier (cur0) was referenced during post-save.","fix":"Guarded with a typeof money0 check so income posts save cleanly.","session":"a1ee807a"},{"app":"Social LevelUp","category":"crash","title":"Older profiles crash on missing state fields","symptom":"Profiles created before new features crashed on load.","root_cause":"normalize() did not backfill newly added state fields.","fix":"Backfilled the new state fields in normalize() so old profiles load.","session":"a1ee807a"},{"app":"Social LevelUp","category":"crash","title":"To-do done button crash","symptom":"Clicking a to-do's done button threw undefined.split.","root_cause":"The attribute was written as data-tododone but read as dataset.todoDone (case mismatch).","fix":"Aligned the dataset key naming so the done button reads correctly.","session":"a1ee807a"},{"app":"Unknown","category":"ui","title":"Screenshot box completely unstyled","symptom":"A box looked cheap because it had no styling at all.","root_cause":"The element rendered completely unstyled.","fix":"Applied proper styling to the box.","session":"2d2c2119"}];
